// One endpoint, three authorization levels — all server-side.
const express = require("express")
const app = express()

function requireAuth(req, res, next) {
  const session = sessions.get(req.cookies.sid)
  if (!session) return res.status(401).end()
  req.session = session
  next()
}

function requireRole(role) {
  return (req, res, next) => {
    if (!req.session.roles.includes(role)) return res.status(403).end()
    next()
  }
}

// Object access: ownership scoped in the query (IDOR defense).
app.get("/invoices/:id", requireAuth, async (req, res) => {
  const invoice = await db.invoices.findOne({
    id: req.params.id,
    ownerId: req.session.userId // never trust req.body.userId here
  })
  // 404, not 403: do not reveal that someone else's invoice exists.
  if (!invoice) return res.status(404).end()
  res.json(invoice)
})

// Admin action: explicit gate + append-only audit.
app.post("/invoices/:id/refund", requireAuth, requireRole("admin"),
  async (req, res) => {
    const invoice = await db.invoices.findOne({ id: req.params.id })
    if (!invoice) return res.status(404).end()
    await refunds.issue(invoice)
    audit.append({
      action: "invoice.refund",
      actor: req.session.userId,
      object: invoice.id,
      at: new Date().toISOString()
    })
    res.status(204).end()
  })

